import { Check, CircleAlert, LoaderCircle, Play } from 'lucide-react';
import { useLanguageServiceContext } from '@/context/LanguageServiceContext';
import { useGameContext } from '@/context/GameContext';
import CodeEditor from './CodeEditor';

const isMac = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.platform);

function Status() {
  const { status, error } = useLanguageServiceContext();
  const { elements } = useGameContext();
  if (status === 'compiling')
    return (
      <span className="flex items-center gap-1.5 text-muted-foreground">
        <LoaderCircle className="size-3.5 animate-spin" /> Reading your code
      </span>
    );
  if (status === 'error' && error)
    return (
      <span className="flex items-center gap-1.5 text-destructive">
        <CircleAlert className="size-3.5" /> {error.line ? `Problem on line ${error.line}` : 'Problem found'}
      </span>
    );
  if (status === 'ok')
    return (
      <span className="flex items-center gap-1.5 text-success">
        <Check className="size-3.5" /> Running · {elements.length} {elements.length === 1 ? 'element' : 'elements'}
      </span>
    );
  return <span className="text-muted-foreground">Not running yet</span>;
}

function ErrorCard() {
  const { error, status } = useLanguageServiceContext();
  if (status !== 'error' || !error) return null;
  return (
    <div role="alert" className="mx-3 mb-3 rounded-xl border border-destructive/30 bg-destructive/8 px-4 py-3">
      <p className="text-sm font-semibold text-destructive">{error.title}</p>
      <p className="mt-1 text-sm text-foreground/85">{error.hint}</p>
      {error.hint !== error.raw && (
        <details className="mt-2 text-xs text-muted-foreground">
          <summary className="cursor-pointer select-none">Show the exact message</summary>
          <pre className="mt-1 font-mono whitespace-pre-wrap">{error.raw}</pre>
        </details>
      )}
    </div>
  );
}

export default function EditorPane() {
  const { compile, isCompiling } = useLanguageServiceContext();
  return (
    <section aria-label="Code" className="flex min-h-0 min-w-0 flex-col bg-editor">
      <div className="flex h-12 shrink-0 items-center gap-3 border-b border-border/70 px-3">
        <button
          type="button"
          onClick={compile}
          disabled={isCompiling}
          className="btn-run inline-flex h-8 items-center gap-1.5 rounded-lg px-3.5 text-sm font-semibold"
        >
          <Play className="size-3.5 fill-current" />
          Run
          <kbd className="ml-1 hidden rounded bg-black/10 px-1 font-sans text-[11px] font-medium sm:inline">
            {isMac ? '⌘' : 'Ctrl'} ↵
          </kbd>
        </button>
        <div className="text-[13px]" aria-live="polite">
          <Status />
        </div>
      </div>
      <CodeEditor />
      <ErrorCard />
    </section>
  );
}
/** End Code Generated by Claude on 2026-11-25 */
